145	    /** Add a claim with the external reference {@code ref} (none when null), refused when another claim
146	     * on the sheet has it (compared without regard to case), and the tags {@code tags} (see
147	     * {@link Claim#tagsOf}; none when null). */
148	    @Transactional
149	    public Claim add(String sheetId, String user, long personId, BigDecimal amount, LocalDate date, String note,
150	            String corrects, String ref, String tags) {
151	        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
152	        RollupService.Snapshot before = rollup.snapshot(sheetId);
153	        LocalDate dated = date != null ? date : sheets.entryDate(sheetId);
154	        int terms = termsOf(sheetId, person, dated);
155	        LocalDate dueBy = holidays.dueBy(sheetId, dated, terms);
156	        refuseClosed(sheetId, dueBy);
157	        person.requireClaimable(dated);
158	        refuseBadCorrection(sheetId, personId, amount, corrects);
159	        refuseRefTaken(sheetId, null, ref);
160	        Claim claim = new Claim(sheetId, personId, amount, dated, noteOf(note), corrects);
161	        claim.setRef(ref);
162	        claim.setTags(tags);
163	        claim.fixTerms(dated, terms);
164	        claim.setDueBy(dueBy);
165	        claim.setListed(sheets.nextInSequence(sheetId, "listed"));
166	        claim.setLateEntry(periods.softClosedOn(sheetId, dueBy));
167	        claim = claims.saveAndFlush(claim);
168	        log(user, person, claim);
169	        keepTags(claim);
170	        List<String> extra = new ArrayList<>();
171	        if (ref != null) extra.add("ref=" + ref);
172	        if (tags != null) extra.add("tags=" + tags);
173	        record("CLAIM_ADDED", user, person, claim, claim.getNumber(), extra.toArray(String[]::new));
174	        if (claim.isLateEntry()) record("LATE_ENTRY", user, person, claim, claim.getNumber());
175	        rollup.recordSince(sheetId, user, before);
176	        return claim;
177	    }
