179	    @Transactional
180	    public Claim update(String sheetId, String user, long claimId, BigDecimal amount, LocalDate date, String note,
181	            String corrects, String ref, String tags) {
182	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
183	        if (claim.isLockedFor(user, sheets.today(sheetId))) throw new ClaimLockedException();
184	        LocalDate dated = date != null ? date : sheets.entryDate(sheetId);
185	        refuseClosed(sheetId, claim.getDueBy());
186	        refuseClosed(sheetId, holidays.dueBy(sheetId, dated, claim.getTerms()));
187	        if (claim.getStatus() != ClaimStatus.DRAFT) throw new ClaimNotEditableException();
188	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
189	                .orElseThrow(PersonNotFoundException::new);
190	        person.requireClaimable(dated);
191	        refuseBadCorrection(sheetId, person.getId(), amount, corrects);
192	        refuseRefTaken(sheetId, claim.getId(), ref);
193	        RollupService.Snapshot before = rollup.snapshot(sheetId);
194	        claim.setAmount(amount);
195	        claim.setCorrects(corrects);
196	        claim.setDate(dated);
197	        claim.setNote(noteOf(note));
198	        claim.setRef(ref);
199	        claim.setTags(tags);
200	        claim.setEditedBy(user);
201	        keepTags(claim);
202	        claim.unlock();
203	        claims.flush();
204	        record("CLAIM_EDITED", user, person, claim, claim.getNumber());
205	        rollup.recordSince(sheetId, user, before);
206	        return claim;
207	    }
