209	    /** Open the claim's editor for {@code user}, locking the claim for everyone else until it is saved
210	     * (see {@link #update}) or cancelled (see {@link #unlock}), or the sheet's today changes. Refused,
211	     * taking no lock, when the claim cannot be edited (not a DRAFT, or dated in a closed period) or
212	     * another user holds its lock. */
213	    @Transactional
214	    public Claim lock(String sheetId, String user, long claimId) {
215	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
216	        LocalDate today = sheets.today(sheetId);
217	        refuseClosed(sheetId, claim.getDueBy());
218	        if (claim.getStatus() != ClaimStatus.DRAFT) throw new ClaimNotEditableException();
219	        if (claim.isLockedFor(user, today)) throw new ClaimLockedException();
220	        claim.lock(user, today);
221	        return claim;
222	    }
