224	    /** Close {@code user}'s editor of the claim without saving, releasing the lock it holds; a lock
225	     * another user holds is left alone. */
226	    @Transactional
227	    public Claim unlock(String sheetId, String user, long claimId) {
228	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
229	        if (user.equals(claim.getLockedBy())) claim.unlock();
230	        return claim;
231	    }
