233	    /** Move the claim to {@code next}; refused when the user's role may not open, settle or void it (see
234	     * {@link SettingsService#allowed}), and when its current status does not allow it (a PENDING
235	     * claim can only be voided here: it is approved or rejected instead). Settling it fixes what is due
236	     * on it then (the figure it is bound to, when a statement bound it, otherwise its person's rate then)
237	     * together with its late charge then (none on a correction); the user who opened it or last edited it
238	     * cannot settle it,
239	     * and a clerk's settle of it when that due is above the sheet's clerk limit (a due that is n/a is
240	     * within any limit) leaves it PENDING instead, fixing nothing, until a steward approves or rejects
241	     * it. A claim deferred on the sheet's today cannot be settled, nor one without proofs whose due is
242	     * above the proof threshold in force on its date (refused before the clerk limit is considered). A
243	     * SETTLED claim can only be voided by a steward, and only while the sheet's today is at most 7 days
244	     * after its settlement (its status log's SETTLED date); its frozen figure then leaves every total and
245	     * is recorded as reversed. A voided claim keeps its number, if it had one. */
246	    @Transactional
247	    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus next) {
248	        return changeStatus(sheetId, user, claimId, next, null);
249	    }
250	
251	    /** Move the claim to {@code next} as {@link #changeStatus(String, String, long, ClaimStatus)} does;
252	     * a void is given {@code voidReason}, which while the sheet's list of void reasons is not empty must
253	     * be one on it (see {@link VoidReasonService#refuseUnlisted}), and is kept on the claim. */
254	    @Transactional
255	    public Claim changeStatus(String sheetId, String user, long claimId, ClaimStatus next, String voidReason) {
256	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
257	        Action action = switch (next) {
258	            case OPEN -> Action.OPEN;
259	            case SETTLED -> Action.SETTLE;
260	            case VOID -> Action.VOID;
261	            default -> null;
262	        };
263	        if (action != null && !settings.allowed(sheetId, user, action)) throw new ClaimNotStewardException();
264	        refuseClosed(sheetId, claim.getDueBy());
265	        if (!claim.getStatus().canBecome(next) || (claim.getStatus() == ClaimStatus.PENDING && next != ClaimStatus.VOID)) {
266	            throw new ClaimStatusChangeException();
267	        }
268	        boolean reversing = claim.getStatus() == ClaimStatus.SETTLED;
269	        if (reversing) refuseLateVoid(sheetId, user, claim);
270	        String reason = next == ClaimStatus.VOID ? voidReasons.refuseUnlisted(sheetId, voidReason) : null;
271	        if (next == ClaimStatus.SETTLED && claim.isDeferredOn(sheets.today(sheetId))) throw new ClaimStatusChangeException();
272	        if (next == ClaimStatus.SETTLED && claim.isOpenedOrEditedBy(user)) throw new ClaimSelfSettleException();
273	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
274	                .orElseThrow(PersonNotFoundException::new);
275	        if (next == ClaimStatus.OPEN) refuseNoteless(claim, rollup.shownOf(claim, person));
276	        RollupService.Snapshot before = rollup.snapshot(sheetId);
277	        String number = claim.getNumber();
278	        if (next == ClaimStatus.OPEN) {
279	            number = nextNumber(sheetId, claim.getDueBy());
280	            claim.setOpenedBy(user);
281	        }
282	        if (next == ClaimStatus.SETTLED) {
283	            BigDecimal figure = claim.isStated() ? claim.getStatedDue() : rollup.dueOf(claim, person);
284	            BigDecimal due = rollup.liveDueOf(claim, figure);
285	            refuseUnproved(claim, person, due);
286	            if (overLimit(sheetId, user, due)) next = ClaimStatus.PENDING;
287	            else claim.setSettledDue(due);
288	        }
289	        claim.setStatus(next);
290	        claim.setNumber(number);
291	        if (next == ClaimStatus.VOID) claim.setVoidReason(reason);
292	        claims.flush();
293	        log(user, person, claim);
294	        String event = switch (next) {
295	            case OPEN -> "CLAIM_OPENED";
296	            case PENDING -> "CLAIM_PENDING";
297	            case SETTLED -> "CLAIM_SETTLED";
298	            case VOID -> "CLAIM_VOIDED";
299	            case DRAFT -> throw new IllegalStateException();
300	        };
301	        if (next == ClaimStatus.SETTLED) {
302	            record(event, user, person, claim, number, "due=" + dueText(claim.getSettledDue()));
303	            notifyWatchers(user, person, claim);
304	        } else {
305	            List<String> extra = new ArrayList<>();
306	            if (reversing) extra.add("reversed=" + dueText(claim.getSettledDue()));
307	            if (reason != null) extra.add("reason=" + reason);
308	            record(event, user, person, claim, number, extra.toArray(String[]::new));
309	        }
310	        rollup.recordSince(sheetId, user, before);
311	        return claim;
312	    }
