334	    /** Remind an OPEN or PENDING claim: a reminder is written and the claim is reminded on the sheet's
335	     * today. Refused unless the claim is OPEN or PENDING, when it was already reminded on the sheet's
336	     * today, and when its due-by is in a closed period. */
337	    @Transactional
338	    public Claim remind(String sheetId, String user, long claimId) {
339	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
340	        if (claim.getStatus() != ClaimStatus.OPEN && claim.getStatus() != ClaimStatus.PENDING) {
341	            throw new ClaimStatusChangeException();
342	        }
343	        LocalDate today = sheets.today(sheetId);
344	        if (today.equals(claim.getRemindedOn())) throw new ClaimRemindedException();
345	        refuseClosed(sheetId, claim.getDueBy());
346	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
347	                .orElseThrow(PersonNotFoundException::new);
348	        claim.setRemindedOn(today);
349	        claims.flush();
350	        record("REMIND", user, person, claim, claim.getNumber());
351	        return claim;
352	    }
