378	    /** Split {@code amount} (more than 0.00 and less than the claim's amount) off an OPEN claim: the
379	     * claim keeps the rest and loses any figure a statement bound it to; a new OPEN claim of the split-off
380	     * amount, with the same person, date and note, is given the next number, is opened by the user, has
381	     * its due-by fixed now from the terms in force on its date and names the claim's number as the one
382	     * it was split from; it is a late entry when that due-by falls in a soft-closed period. Refused unless
383	     * the claim is OPEN and not deferred on the sheet's today, and when its due-by or the new claim's falls
384	     * in a closed period. Both claims are returned, the original first. */
385	    @Transactional
386	    public List<Claim> split(String sheetId, String user, long claimId, BigDecimal amount) {
387	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
388	        refuseClosed(sheetId, claim.getDueBy());
389	        if (claim.getStatus() != ClaimStatus.OPEN || claim.isDeferredOn(sheets.today(sheetId))) {
390	            throw new ClaimStatusChangeException();
391	        }
392	        if (amount.signum() <= 0 || amount.compareTo(claim.getAmount()) >= 0) throw new ClaimSplitException();
393	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
394	                .orElseThrow(PersonNotFoundException::new);
395	        RollupService.Snapshot before = rollup.snapshot(sheetId);
396	        claim.setAmount(claim.getAmount().subtract(amount));
397	        claim.unbind();
398	        Claim split = new Claim(sheetId, person.getId(), amount, claim.getDate(), claim.getNote(), null);
399	        int terms = termsOf(sheetId, person, claim.getDate());
400	        split.fixTerms(claim.getDate(), terms);
401	        split.setDueBy(holidays.dueBy(sheetId, claim.getDate(), terms));
402	        refuseClosed(sheetId, split.getDueBy());
403	        split.setLateEntry(periods.softClosedOn(sheetId, split.getDueBy()));
404	        split.setListed(sheets.nextInSequence(sheetId, "listed"));
405	        split.setStatus(ClaimStatus.OPEN);
406	        split.setNumber(nextNumber(sheetId, split.getDueBy()));
407	        split.setOpenedBy(user);
408	        split.setSplitFrom(claim.getNumber());
409	        split.setTags(claim.getTags().isEmpty() ? null : String.join(",", claim.getTags()));
410	        split = claims.saveAndFlush(split);
411	        log(user, person, split);
412	        record("CLAIM_SPLIT", user, person, claim, claim.getNumber(), "into=" + split.getNumber());
413	        record("CLAIM_OPENED", user, person, split, split.getNumber());
414	        rollup.recordSince(sheetId, user, before);
415	        return List.of(claim, split);
416	    }
