442	    /** Raise the claim's proofs count by one. Refused when the claim is SETTLED or VOID, and when it is
443	     * dated in a closed period. */
444	    @Transactional
445	    public Claim addProof(String sheetId, String user, long claimId) {
446	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
447	        refuseClosed(sheetId, claim.getDueBy());
448	        if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) {
449	            throw new ClaimStatusChangeException();
450	        }
451	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
452	                .orElseThrow(PersonNotFoundException::new);
453	        claim.addProof();
454	        claims.flush();
455	        record("CLAIM_PROOF_ADDED", user, person, claim, claim.getNumber(), "proofs=" + claim.getProofs());
456	        return claim;
457	    }
