459	    /** A steward's rejection of a PENDING claim, for {@code reason}: it goes back to OPEN, bound again
460	     * by its person's last statement if that statement included it. Refused unless the claim is
461	     * PENDING, and when the user is not a steward. */
462	    @Transactional
463	    public Claim reject(String sheetId, String user, long claimId, String reason) {
464	        Claim claim = lockPending(sheetId, user, claimId);
465	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
466	                .orElseThrow(PersonNotFoundException::new);
467	        RollupService.Snapshot before = rollup.snapshot(sheetId);
468	        claim.setStatus(ClaimStatus.OPEN);
469	        claims.flush();
470	        log(user, person, claim);
471	        record("CLAIM_REJECTED", user, person, claim, claim.getNumber(), "reason=" + reason);
472	        rollup.recordSince(sheetId, user, before);
473	        return claim;
474	    }
475	
476	    /** A move, by a role the permission matrix allows to reassign (a steward by default), of a DRAFT, OPEN or PENDING claim to another person on the sheet. It keeps its
477	     * number and date, loses any figure a statement bound it to (it is live again until its new
478	     * person's next statement), and is listed as its new person's newest claim. Refused when the user's
479	     * role may not reassign, when the claim is SETTLED or VOID, is a correction (it corrects a claim of its
480	     * own person) or already belongs to the person, when it is dated in a closed period, and when it
481	     * is dated after the new person's retirement date. */
482	    @Transactional
483	    public Claim reassign(String sheetId, String user, long claimId, long personId) {
484	        return move(sheetId, user, claimId, personId, false);
485	    }
486	
487	    /** A move of one of several claims moved together: by the rules of {@link #reassign}, except that a
488	     * claim that already belongs to the person goes through (it is listed as the person's newest claim,
489	     * and recorded). */
490	    @Transactional
491	    public Claim reassignOfBulk(String sheetId, String user, long claimId, long personId) {
492	        return move(sheetId, user, claimId, personId, true);
493	    }
494	
495	    private Claim move(String sheetId, String user, long claimId, long personId, boolean samePerson) {
496	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
497	        if (!settings.allowed(sheetId, user, Action.REASSIGN)) throw new ClaimNotStewardException();
498	        refuseClosed(sheetId, claim.getDueBy());
499	        ClaimStatus status = claim.getStatus();
500	        if ((status != ClaimStatus.DRAFT && status != ClaimStatus.OPEN && status != ClaimStatus.PENDING)
501	                || claim.isCorrection() || (!samePerson && claim.getPersonId() == personId)) {
502	            throw new ClaimReassignException();
503	        }
504	        Person from = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
505	                .orElseThrow(PersonNotFoundException::new);
506	        Person to = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
507	        to.requireClaimable(claim.getDate());
508	        RollupService.Snapshot before = rollup.snapshot(sheetId);
509	        claim.setPersonId(to.getId());
510	        claim.unbind();
511	        claim.setListed(sheets.nextInSequence(sheetId, "listed"));
512	        claims.flush();
513	        record("CLAIM_REASSIGNED", user, to, claim, claim.getNumber(), "from=" + from.getName(), "to=" + to.getName());
514	        rollup.recordSince(sheetId, user, before);
515	        return claim;
516	    }
517	
518	    /** A steward's re-settle of a SETTLED claim: it is fixed again at what would be due on it now were
519	     * it OPEN and bound by no statement (its person's rate and grade, the sheet's floor and its late
520	     * charge, all as they are now). Refused unless the claim is SETTLED, when the user is not a
521	     * steward, and when it is dated in a closed period. */
522	    @Transactional
523	    public Claim resettle(String sheetId, String user, long claimId) {
524	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
525	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
526	        refuseClosed(sheetId, claim.getDueBy());
527	        if (claim.getStatus() != ClaimStatus.SETTLED) throw new ClaimStatusChangeException();
528	        Person person = people.findByIdAndSheetId(claim.getPersonId(), sheetId)
529	                .orElseThrow(PersonNotFoundException::new);
530	        RollupService.Snapshot before = rollup.snapshot(sheetId);
531	        BigDecimal old = claim.getSettledDue();
532	        BigDecimal due = rollup.openShownOf(claim, person);
533	        claim.setSettledDue(due);
534	        claims.flush();
535	        log(user, person, claim);
536	        record("CLAIM_RESETTLED", user, person, claim, claim.getNumber(), "old=" + dueText(old), "new=" + dueText(due));
537	        notifyWatchers(user, person, claim);
538	        rollup.recordSince(sheetId, user, before);
539	        return claim;
540	    }
541	
542	    /** Refuse a void of the SETTLED claim unless the user is a steward and the sheet's today is at most
543	     * 7 days after the date its status log first shows it SETTLED. */
544	    private void refuseLateVoid(String sheetId, String user, Claim claim) {
545	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
546	        LocalDate settled = logs.findByClaimIdInOrderByIdAsc(List.of(claim.getId())).stream()
547	                .filter(entry -> entry.getStatus() == ClaimStatus.SETTLED)
548	                .map(ClaimLog::getDate)
549	                .findFirst()
550	                .orElseThrow(ClaimStatusChangeException::new);
551	        if (sheets.today(sheetId).isAfter(settled.plusDays(7))) throw new ClaimVoidLateException();
552	    }
553	
554	    /** The PENDING claim, locked, for a steward to approve or reject. */
555	    private Claim lockPending(String sheetId, String user, long claimId) {
556	        Claim claim = claims.lockByIdAndSheetId(claimId, sheetId).orElseThrow(ClaimNotFoundException::new);
557	        refuseClosed(sheetId, claim.getDueBy());
558	        if (claim.getStatus() != ClaimStatus.PENDING) throw new ClaimStatusChangeException();
559	        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new ClaimNotStewardException();
560	        return claim;
561	    }
562	
563	    private static String dueText(BigDecimal due) {
564	        return due == null ? "n/a" : due.toPlainString();
565	    }
566	
567	    /** The figure the claim shows and totals now, without its late charge or floor; null when it has no figure
568	     * (see {@link RollupService#figureOf}). */
569	    public BigDecimal figureOf(Claim claim, Person person) {
570	        return rollup.figureOf(claim, person);
571	    }
572	
573	    /** What is due on the claim as it shows and totals now, its late charge included; null when it has
574	     * no figure (see {@link RollupService#shownOf}). */
575	    public BigDecimal shownOf(Claim claim, Person person) {
576	        return rollup.shownOf(claim, person);
577	    }
578	
579	    /** Keep each of the claim's tags among those ever used on its sheet. */
580	    private void keepTags(Claim claim) {
581	        for (String tag : claim.getTags()) {
582	            SheetTag.Key key = new SheetTag.Key(claim.getSheetId(), tag);
583	            if (!tagRepository.existsById(key)) tagRepository.save(new SheetTag(claim.getSheetId(), tag));
584	        }
585	    }
586	
587	    /** Write the status the claim has now to its log, with the sheet's today and what is due on it as
588	     * it shows now. */
589	    private void log(String user, Person person, Claim claim) {
590	        logs.save(new ClaimLog(claim.getId(), claim.getStatus(), user, sheets.today(claim.getSheetId()),
591	                rollup.shownOf(claim, person)));
592	    }
593	
594	    /** Record a change to the claim; {@code number}, the number it has (or had), follows when there is one,
595	     * then any {@code extra} fields. */
596	    private void record(String event, String user, Person person, Claim claim, String number, String... extra) {
597	        List<String> fields = new ArrayList<>(List.of("person=" + person.getName(),
598	                "amount=" + claim.getAmount().setScale(2, RoundingMode.UNNECESSARY).toPlainString(),
599	                "date=" + claim.getDate()));
600	        if (number != null) fields.add("number=" + number);
601	        fields.addAll(List.of(extra));
602	        audit.change(event, claim.getSheetId(), user, fields.toArray(String[]::new));
603	    }
604	
605	    /** Notify each user watching the person, in the order they started watching, that the claim was
606	     * settled, approved or re-settled. */
607	    private void notifyWatchers(String user, Person person, Claim claim) {
608	        for (PersonWatch watch : watches.findByPersonIdOrderByIdAsc(person.getId())) {
609	            audit.change("NOTIFY", claim.getSheetId(), user, "user=" + watch.getUser(), "person=" + person.getName(),
610	                    "number=" + claim.getNumber());
611	        }
612	    }
613	
614	    /** The number a claim due by {@code date} is given when opened now: within the period containing
615	     * that date ({@code <period name>-<n>}, or {@code X-<n>} when none does) while the sheet numbers by
616	     * period, otherwise the next sheet-wide number. */
617	    private String nextNumber(String sheetId, LocalDate date) {
618	        if (!sheets.numbersByPeriod(sheetId)) return String.valueOf(sheets.nextClaimNumber(sheetId));
619	        return periods.findBySheetIdOrderByFromAsc(sheetId).stream()
620	                .filter(p -> !date.isBefore(p.getFrom()) && !date.isAfter(p.getTo()))
621	                .findFirst()
622	                .map(p -> p.getName() + "-" + sheets.nextInSequence(sheetId, "period:" + p.getId()))
623	                .orElseGet(() -> "X-" + sheets.nextInSequence(sheetId, "none"));
624	    }
625	
626	    /** Whether a settle by {@code user} of a claim whose due is {@code due} needs a steward's approval:
627	     * the user is a clerk and the due is above the sheet's clerk limit. */
628	    private boolean overLimit(String sheetId, String user, BigDecimal due) {
629	        if (due == null || settings.roleOf(sheetId, user) == Role.STEWARD) return false;
630	        BigDecimal limit = settings.clerkLimit(sheetId);
631	        return limit != null && due.compareTo(limit) > 0;
632	    }
633	
634	    /** Refuse a settle or approval of the claim, whose due is {@code due}, while it has no proofs and that
635	     * due is above the proof threshold in force on its date: its person's grade's own then, else the sheet's
636	     * (a due that is n/a is within any threshold). */
637	    private void refuseUnproved(Claim claim, Person person, BigDecimal due) {
638	        if (due == null || claim.getProofs() > 0) return;
639	        BigDecimal threshold = settings.proofThresholdFor(claim.getSheetId(), person.gradeOn(claim.getDate()), claim.getDate());
640	        if (threshold != null && due.compareTo(threshold) > 0) throw new ClaimProofRequiredException();
641	    }
642	
643	    /** Refuse an open of the claim, whose due is {@code due}, while its note is empty and that due is
644	     * above the note threshold in force on its date (a due that is n/a is within any threshold). */
645	    private void refuseNoteless(Claim claim, BigDecimal due) {
646	        if (due == null || !noteOf(claim.getNote()).isEmpty()) return;
647	        BigDecimal threshold = settings.noteThresholdOn(claim.getSheetId(), claim.getDate());
648	        if (threshold != null && due.compareTo(threshold) > 0) throw new ClaimNoteRequiredException();
649	    }
650	
651	    /** Refuse a correction (a negative {@code amount}) that does not name, by number, a SETTLED claim of
652	     * the person, and a claim that names one without being a correction. */
653	    private void refuseBadCorrection(String sheetId, Long personId, BigDecimal amount, String corrects) {
654	        if (amount.signum() >= 0) {
655	            if (corrects != null) throw new ClaimCorrectionException();
656	            return;
657	        }
658	        if (corrects == null) throw new ClaimCorrectionException();
659	        claims.findBySheetIdAndPersonIdAndNumber(sheetId, personId, corrects)
660	                .filter(corrected -> corrected.getStatus() == ClaimStatus.SETTLED)
661	                .orElseThrow(ClaimCorrectionException::new);
662	    }
663	
664	    /** Refuse the external reference {@code ref} when a claim on the sheet other than {@code claimId} has
665	     * it, compared without regard to case. */
666	    private void refuseRefTaken(String sheetId, Long claimId, String ref) {
667	        if (ref == null) return;
668	        claims.findBySheetIdAndRefKey(sheetId, Claim.keyOf(ref))
669	                .filter(other -> !other.getId().equals(claimId))
670	                .ifPresent(other -> {
671	                    throw new ClaimRefTakenException();
672	                });
673	    }
674	
675	    /** Refuse a change to a claim due by {@code date} when a closed period of the sheet contains it. */
676	    private void refuseClosed(String sheetId, LocalDate date) {
677	        if (periods.closedOn(sheetId, date)) throw new ClaimPeriodClosedException();
678	    }
679	
680	    private static String noteOf(String note) {
681	        return note == null ? "" : note.trim();
682	    }
683	
684	    /** The terms a claim of the person dated {@code date} is due by: the person's own terms, else those
685	     * of their grade in force on that date, else the sheet's then. */
686	    private int termsOf(String sheetId, Person person, LocalDate date) {
687	        return person.getTerms() != null ? person.getTerms() : settings.termsFor(sheetId, person.gradeOn(date), date);
688	    }
689	}
