    @ElementCollection(fetch = FetchType.EAGER)
    @CollectionTable(name = "period_person_total", joinColumns = @JoinColumn(name = "period_id"))
    @MapKeyColumn(name = "person_id")
    @Column(name = "total", precision = 12, scale = 2, nullable = false)
    private Map<Long, BigDecimal> closedPersonTotals = new HashMap<>();

    protected Period() {
    }

    public Period(String sheetId, String name, LocalDate from, LocalDate to) {
        this.sheetId = sheetId;
        this.name = name.trim();
        this.nameKey = keyOf(name);
        this.from = from;
        this.to = to;
    }

    /** The name as compared: without the spaces around it, in lower case. */
    public static String keyOf(String name) {
        return name.trim().toLowerCase(Locale.ROOT);
    }

    public Long getId() {
        return id;
    }

    public String getSheetId() {
        return sheetId;
    }

    public String getName() {
        return name;
    }

    public LocalDate getFrom() {
        return from;
    }

    public LocalDate getTo() {
        return to;
    }

    public boolean isClosed() {
        return closed;
    }

    public boolean isSoft() {
        return soft;
    }

    public BigDecimal getClosedTotal() {
        return closedTotal;
    }

    public Map<Long, BigDecimal> getClosedPersonTotals() {
        return Map.copyOf(closedPersonTotals);
    }

    /** Close the period, fixing each person's due-total for it at {@code personTotals}, by person id,
     * and its own due-total at their sum. */
    public void close(Map<Long, BigDecimal> personTotals) {
        close(personTotals, false);
    }

    /** Close the period as {@link #close(Map)} does, soft-closed when {@code soft}. */
    public void close(Map<Long, BigDecimal> personTotals, boolean soft) {
        this.closed = true;
        this.soft = soft;
        this.closedPersonTotals.clear();
        this.closedPersonTotals.putAll(personTotals);
        this.closedTotal = personTotals.values().stream().reduce(BigDecimal.ZERO.setScale(2), BigDecimal::add);
    }

    /** Reopen the period: its due-total is live again. */
    public void reopen() {
        this.closed = false;
        this.soft = false;
        this.closedTotal = null;
        this.closedPersonTotals.clear();
    }

    /** Whether this period shares a day with the dates {@code from} to {@code to}, both inclusive. */
    public boolean overlaps(LocalDate from, LocalDate to) {
        return !this.from.isAfter(to) && !from.isAfter(this.to);
    }
}
package net.officefloor.hq.app.period;


/** The periods of each sheet: uniquely named, none overlapping another. A period can be closed, which
 * fixes its due-total then, and a steward (or the roles the permission matrix allows) can reopen it, which makes its due-total live again. */
@Service
public class PeriodService {

    private final PeriodRepository periods;
    private final SheetRepository sheets;
    private final ClaimRepository claims;
    private final ClaimLogRepository logs;
    private final PersonRepository people;
    private final RollupService rollup;
    private final SettingsService settings;
    private final Audit audit;

    public PeriodService(PeriodRepository periods, SheetRepository sheets, ClaimRepository claims,
            ClaimLogRepository logs, PersonRepository people, RollupService rollup, SettingsService settings, Audit audit) {
        this.periods = periods;
        this.sheets = sheets;
        this.claims = claims;
        this.logs = logs;
        this.people = people;
        this.rollup = rollup;
        this.settings = settings;
        this.audit = audit;
    }

    /** The sheet's periods, by from-date. */
    @Transactional(readOnly = true)
    public List<Period> list(String sheetId) {
        return periods.findBySheetIdOrderByFromAsc(sheetId);
    }

    @Transactional
    public Period add(String sheetId, String user, String name, LocalDate from, LocalDate to) {
        if (!sheets.existsById(sheetId)) {
            throw new SheetNotFoundException();
        }
        if (to.isBefore(from)) {
            throw new PeriodRefusedException("to before from");
        }
        if (periods.findBySheetIdAndNameKey(sheetId, Period.keyOf(name)).isPresent()) {
            throw new PeriodRefusedException("name taken");
        }
        if (periods.findBySheetIdOrderByFromAsc(sheetId).stream().anyMatch(p -> p.overlaps(from, to))) {
            throw new PeriodRefusedException("overlaps");
        }
        Period period = periods.saveAndFlush(new Period(sheetId, name, from, to));
        audit.change("PERIOD_ADDED", sheetId, user, "period=" + period.getName(), "from=" + period.getFrom(),
                "to=" + period.getTo());
        return period;
    }

    /** Make one period per calendar month from the from-date's month to the to-date's month, each from
     * the first to the last day of its month and named yyyy-mm, in order; a month whose name is
     * already a period's or whose days overlap a period on the sheet is left out. A missing date is
     * the sheet's today; a to-date before the from-date is refused. */
    @Transactional
    public List<Period> generate(String sheetId, String user, LocalDate from, LocalDate to) {
        Sheet sheet = sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new);
        LocalDate start = from == null ? sheet.getToday() : from;
        LocalDate end = to == null ? sheet.getToday() : to;
        if (end.isBefore(start)) {
            throw new PeriodRefusedException("to before from");
        }
        List<Period> existing = new ArrayList<>(periods.findBySheetIdOrderByFromAsc(sheetId));
        List<Period> made = new ArrayList<>();
        for (YearMonth month = YearMonth.from(start); !month.isAfter(YearMonth.from(end)); month = month.plusMonths(1)) {
            String name = month.toString();
            LocalDate first = month.atDay(1);
            LocalDate last = month.atEndOfMonth();
            String key = Period.keyOf(name);
            if (existing.stream().anyMatch(p -> Period.keyOf(p.getName()).equals(key) || p.overlaps(first, last))) {
                continue;
            }
            Period period = periods.saveAndFlush(new Period(sheetId, name, first, last));
            audit.change("PERIOD_ADDED", sheetId, user, "period=" + period.getName(), "from=" + period.getFrom(),
                    "to=" + period.getTo());
            existing.add(period);
            made.add(period);
        }
        return made;
    }

    /** Close the period, fixing its due-total now (afresh when it was soft-closed); refused when the
     * user's role may not close (see {@link SettingsService#allowed}) or it is already closed, not
     * only soft-closed. */
    @Transactional
    public Period close(String sheetId, String user, long periodId) {
        Period period = periods.lockByIdAndSheetId(periodId, sheetId).orElseThrow(PeriodNotFoundException::new);
        if (!settings.allowed(sheetId, user, Action.CLOSE)) {
            throw new PeriodNotStewardException();
        }
        if (period.isClosed() && !period.isSoft()) {
            throw new PeriodRefusedException("already closed");
        }
        return close(period, user);
    }

    /** Soft-close the period, fixing its due-total now while claims dated in it can still change;
     * refused as {@link #close(String, String, long)} is, and when it is already closed or soft-closed. */
    @Transactional
    public Period softClose(String sheetId, String user, long periodId) {
        Period period = periods.lockByIdAndSheetId(periodId, sheetId).orElseThrow(PeriodNotFoundException::new);
        if (!settings.allowed(sheetId, user, Action.CLOSE)) {
            throw new PeriodNotStewardException();
        }
        if (period.isClosed()) {
            throw new PeriodRefusedException("already closed");
        }
        period.close(personTotalsOf(period), true);
        periods.flush();
        audit.change("PERIOD_SOFT_CLOSED", sheetId, user, "period=" + period.getName(),
                "total=" + period.getClosedTotal().toPlainString());
        return period;
    }

    /** Close, as {@link #close(String, String, long)} would, every open period of the sheet whose to-date
     * plus its grace days is before its today, in order of their to-dates, each marked auto=yes; nothing
     * when the grace days are off. An automatic close is not subject to the permission matrix. */
    @Transactional
    public void closeOverdue(String sheetId, String user) {
        Sheet sheet = sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new);
        Integer grace = sheet.getGraceDays();
        if (grace == null) return;
        List<Period> due = periods.findBySheetIdOrderByFromAsc(sheetId).stream()
                .filter(p -> !p.isClosed() && p.getTo().plusDays(grace).isBefore(sheet.getToday()))
                .sorted(Comparator.comparing(Period::getTo)).toList();
        for (Period open : due) {
            Period period = periods.lockByIdAndSheetId(open.getId(), sheetId).orElseThrow(PeriodNotFoundException::new);
            if (!period.isClosed()) close(period, user, "auto=yes");
        }
    }

    private Period close(Period period, String user, String... extra) {
        period.close(personTotalsOf(period));
        periods.flush();
        List<String> fields = new ArrayList<>(List.of("period=" + period.getName(),
                "total=" + period.getClosedTotal().toPlainString()));
        fields.addAll(List.of(extra));
        audit.change("PERIOD_CLOSED", period.getSheetId(), user, fields.toArray(String[]::new));
        return period;
    }

    /** Reopen the period, making its due-total live again; refused when the user's role may not
     * reopen (a steward's by default, see {@link SettingsService#allowed}) or the period is not closed
     * or soft-closed. */
    @Transactional
    public Period reopen(String sheetId, String user, long periodId) {
        Period period = periods.lockByIdAndSheetId(periodId, sheetId).orElseThrow(PeriodNotFoundException::new);
        if (!settings.allowed(sheetId, user, Action.REOPEN)) {
            throw new PeriodNotStewardException();
        }
        if (!period.isClosed()) {
            throw new PeriodRefusedException("not closed");
        }
        period.reopen();
        periods.flush();
        audit.change("PERIOD_REOPENED", sheetId, user, "period=" + period.getName());
        return period;
    }

    /** Each person's due-total for the period now, by person id, for everyone on the sheet: the sum of
     * what is due on their claims whose due-by falls in it that counted by the status each had at the end of the
     * period's last day (see {@link #statusAt}), as each shows it now, late charges included (a
     * claim with no figure adds nothing, nor does an OPEN claim deferred on the sheet's today or an unbound OPEN claim dated within one of its person's holds, while the claim is still OPEN or PENDING now). */
    private Map<Long, BigDecimal> personTotalsOf(Period period) {
        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(period.getSheetId()).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        Map<Long, BigDecimal> totals = new HashMap<>();
        for (Long id : byId.keySet()) totals.put(id, BigDecimal.ZERO.setScale(2));
        LocalDate today = sheets.findById(period.getSheetId()).map(Sheet::getToday).orElse(null);
        List<Claim> dated = claims.findBySheetIdOrderByListedDescIdDesc(period.getSheetId()).stream()
                .filter(claim -> period.overlaps(claim.getDueBy(), claim.getDueBy())).toList();
        Map<Long, List<ClaimLog>> logsOf = dated.isEmpty() ? Map.of()
                : logs.findByClaimIdInOrderByIdAsc(dated.stream().map(Claim::getId).toList()).stream()
                        .collect(Collectors.groupingBy(ClaimLog::getClaimId));
        for (Claim claim : dated) {
            Person person = byId.get(claim.getPersonId());
            ClaimStatus status = statusAt(logsOf.getOrDefault(claim.getId(), List.of()), period.getTo());
            if (person == null || status == null) continue;
            boolean counts = claim.getStatus().isOpen() ? RollupService.countsAs(claim, status, person, today) : status.counts();
            if (!counts) continue;
            BigDecimal figure = rollup.shownOf(claim, person);
            if (figure != null) totals.merge(person.getId(), figure, BigDecimal::add);
        }
        return totals;
    }

    /** The status a claim had at the end of {@code day}, by its status log, oldest first, whose lines
     * are dated with the sheet's today when each change was made; null when it was added after. */
    private static ClaimStatus statusAt(List<ClaimLog> log, LocalDate day) {
        ClaimStatus status = null;
        for (ClaimLog line : log) {
            if (line.getDate().isAfter(day)) break;
            status = line.getStatus();
        }
        return status;
    }
}
package net.officefloor.hq.app.period;


public interface PeriodRepository extends JpaRepository<Period, Long> {

    List<Period> findBySheetIdOrderByFromAsc(String sheetId);

    Optional<Period> findBySheetIdAndNameKey(String sheetId, String nameKey);

    /** The period, locked until the transaction ends so it is never closed twice at once. */
    @Lock(LockModeType.PESSIMISTIC_WRITE)
    @Query("SELECT p FROM Period p WHERE p.id = :id AND p.sheetId = :sheetId")
    Optional<Period> lockByIdAndSheetId(Long id, String sheetId);

    /** Whether a closed period of the sheet, not only soft-closed, contains the date. */
    @Query("SELECT COUNT(p) > 0 FROM Period p WHERE p.sheetId = :sheetId AND p.closed = TRUE AND p.soft = FALSE"
            + " AND p.from <= :date AND p.to >= :date")
    boolean closedOn(String sheetId, LocalDate date);

    /** Whether a soft-closed period of the sheet contains the date. */
    @Query("SELECT COUNT(p) > 0 FROM Period p WHERE p.sheetId = :sheetId AND p.closed = TRUE AND p.soft = TRUE"
            + " AND p.from <= :date AND p.to >= :date")
    boolean softClosedOn(String sheetId, LocalDate date);
}
package net.officefloor.hq.app.statement;


/**
 * The statements taken of the people on each sheet. Taking one binds each of the person's claims that
 * counts (OPEN, PENDING or SETTLED, but not an OPEN one deferred on the sheet's today, nor an unbound OPEN or PENDING one dated within one of their holds) to the figure it shows then, and leaves
 * each that does not count unbound;
 * it records the person's due-total then: the sum of what is due on those claims as each shows it, late
 * charges included (a claim with no figure is skipped), at most the sheet's cap. A late charge is never bound: it keeps following
 * the sheet's today.
 * <p>
 * A steward can cancel a person's last statement: the claims it bound become live again (a figure a
 * statement before it bound is not restored), and the person's statement before it is their last again.
 * <p>
 * A statement can also be taken as of an earlier date, of the sheet as it stood then (see
 * {@link #take(String, String, long, LocalDate)}).
 */
@Service
public class StatementService {

    private final StatementRepository statements;
    private final ClaimRepository claims;
    private final PersonRepository people;
    private final SheetService sheets;
    private final Audit audit;
    private final RollupService rollup;
    private final SettingsService settings;
    private final SheetHistory history;

    public StatementService(StatementRepository statements, ClaimRepository claims,
            PersonRepository people, SheetService sheets, Audit audit, RollupService rollup,
            SettingsService settings, SheetHistory history) {
        this.settings = settings;
        this.history = history;
        this.statements = statements;
        this.claims = claims;
        this.people = people;
        this.sheets = sheets;
        this.audit = audit;
        this.rollup = rollup;
    }

    /** A statement taken, with the person's claims as it left them, newest first. */
    public record Taken(Statement statement, List<Claim> claims) {
    }

    /** The sheet's statements in the order they were taken. */
    @Transactional(readOnly = true)
    public List<Statement> list(String sheetId) {
        return statements.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** Take the person's statement now (see {@link #take(String, String, long, LocalDate)}). */
    @Transactional
    public Taken take(String sheetId, String user, long personId) {
        return take(sheetId, user, personId, null);
    }

    /**
     * Take the person's statement as of {@code asOf}, a date on or before the sheet's today (now when
     * null): it binds their claims that counted at the end of that date to their figures as they stood
     * then — every change made while the sheet's today was on or before it counts, every later one does
     * not, and it stands in for the sheet's today in every figure — and leaves every other claim of theirs
     * unbound. Its date is that date and its due-total that day's. Refused when the date is after the
     * sheet's today, and when the person was not yet on the sheet then.
     */
    @Transactional
    public Taken take(String sheetId, String user, long personId, LocalDate asOf) {
        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
        List<Claim> theirs = claims.lockBySheetIdAndPersonId(sheetId, personId);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        LocalDate today = sheets.today(sheetId);
        if (asOf != null && asOf.isAfter(today)) throw new StatementRefusedException("after the sheet's today");
        // What the statement is taken of: the person and their claims as they stood then, with the
        // rates and settings then, the statement's date standing in for the sheet's today.
        Person then = person;
        List<Claim> stood = theirs;
        RollupService.Basis basis = rollup.live(sheetId);
        if (asOf != null) {
            SheetAsOf sheet = history.asOf(sheetId, asOf);
            then = sheet.person(personId).orElseThrow(() -> new StatementRefusedException("not on the sheet then"));
            stood = sheet.claimsOf(personId);
            basis = sheet;
        }
        LocalDate date = basis.today();
        Map<Long, BigDecimal> figures = new HashMap<>();
        for (Claim claim : stood) {
            if (RollupService.countsLive(claim, then, date)) figures.put(claim.getId(), rollup.figureOf(claim, then, basis));
        }
        int counted = figures.size();
        // The person's due-total as shown (the sum of those claims' figures, at most the sheet's cap): n/a
        // when none of their claims has a figure and no rate applies.
        BigDecimal total = rollup.dueTotalOf(stood, then, basis);
        BigDecimal dueTotal = total == null ? null : total.setScale(2, RoundingMode.HALF_EVEN);
        Statement statement = statements.saveAndFlush(new Statement(sheetId, personId, date, dueTotal, counted));
        for (Claim claim : theirs) {
            if (figures.containsKey(claim.getId())) claim.bind(figures.get(claim.getId()), statement.getId());
            else claim.unbind();
        }
        claims.flush();
        List<String> fields = new ArrayList<>(List.of("name=" + person.getName(),
                "due-total=" + (dueTotal == null ? RollupService.NONE : dueTotal.toPlainString()), "claims=" + counted));
        if (asOf != null) fields.add("asof=" + asOf);
        audit.change("STATEMENT", sheetId, user, fields.toArray(String[]::new));
        rollup.recordSince(sheetId, user, before);
        return new Taken(statement, theirs);
    }

    /** Cancel the person's last statement: the claims it bound become live again. Refused when the user is
     * not a steward of the sheet, and when the person has no statement. */
    @Transactional
    public Taken cancelLast(String sheetId, String user, long personId) {
        Person person = people.findByIdAndSheetId(personId, sheetId).orElseThrow(PersonNotFoundException::new);
        if (settings.roleOf(sheetId, user) != Role.STEWARD) throw new StatementNotStewardException();
        List<Claim> theirs = claims.lockBySheetIdAndPersonId(sheetId, personId);
        Statement last = statements.findFirstBySheetIdAndPersonIdOrderByIdDesc(sheetId, personId)
                .orElseThrow(StatementNotFoundException::new);
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        for (Claim claim : theirs) {
            if (claim.isStated() && last.getId().equals(claim.getStatedBy())) claim.unbind();
        }
        claims.flush();
        statements.delete(last);
        statements.flush();
        audit.change("STATEMENT_CANCELLED", sheetId, user, "name=" + person.getName(), "due-total="
                + (last.getDueTotal() == null ? RollupService.NONE : last.getDueTotal().toPlainString()));
        rollup.recordSince(sheetId, user, before);
        return new Taken(last, theirs);
    }
}

package net.officefloor.hq.app.settings;


/** A sheet's settings: the role each user name has on it (a clerk unless made a steward) and its clerk
 * limit, the most a clerk may settle a claim for (none when null), and its floor, the least a claim's
 * live due can be, and its cap, the most a person's due-total can be (none when null), and its terms, how many business days after its date a claim is due by (each grade may have its own
 * terms in their place), and its late percent, the
 * percent of its figure an overdue claim's due gains for every full 30 days it is overdue, and its policy
 * date, which decides how a claim's live figures round (the sheet's today when none is set), and its
 * period numbering from, the date from which a claim opened is numbered within its period (off when null),
 * and its proof threshold, above which a claim's due needs a proof before it is settled (none when null; each grade may
 * have its own in its place),
 * and its grace days, how many days after its to-date an open period is closed when the sheet's today
 * is changed (off when null), and each grade's grace days, how many days past its due-by a claim of the
 * grade is overdue from (none when null).
 * The settings that carry a figure (the clerk limit, the floor, the cap, the terms, the late percent, the proof threshold and the grades' grace days)
 * are dated: each value is recorded from a date (see {@link DatedSettings}); the policy date, the
 * period numbering from and the grace days are not. Its permission matrix, also not dated, gives for each {@link Action}
 * the roles that may take it; a blank entry keeps the action's standing rule. */
@Service
public class SettingsService {

    private static final List<String> GRADES = List.of("A", "B", "C");

    private final SheetRepository sheets;
    private final SheetRoleRepository roles;
    private final SheetSettingRepository settings;
    private final SheetPermissionRepository permissions;
    private final DatedSettings dated;
    private final RollupService rollup;
    private final DelegationService delegations;
    private final Audit audit;

    public SettingsService(SheetRepository sheets, SheetRoleRepository roles, SheetSettingRepository settings,
            SheetPermissionRepository permissions, DatedSettings dated, RollupService rollup,
            DelegationService delegations, Audit audit) {
        this.delegations = delegations;
        this.permissions = permissions;
        this.sheets = sheets;
        this.roles = roles;
        this.settings = settings;
        this.dated = dated;
        this.rollup = rollup;
        this.audit = audit;
    }

    /** The roles given on the sheet, by user name. */
    @Transactional(readOnly = true)
    public List<SheetRole> roles(String sheetId) {
        return roles.findBySheetIdOrderByUser(sheetId);
    }

    /** The user's role on the sheet: a clerk unless made something else, and a steward while the sheet's
     * today is inside a range the steward role is delegated to them for (see {@link DelegationService}). */
    @Transactional(readOnly = true)
    public Role roleOf(String sheetId, String user) {
        Role given = delegations.givenRole(sheetId, user);
        if (given != Role.STEWARD && delegations.actingFor(sheetId, user).isPresent()) return Role.STEWARD;
        return given;
    }

    @Transactional
    public SheetRole setRole(String sheetId, String by, String user, Role role) {
        if (!sheets.existsById(sheetId)) throw new SheetNotFoundException();
        SheetRole given = roles.findBySheetIdAndUser(sheetId, user).orElse(null);
        if (given == null) {
            given = roles.saveAndFlush(new SheetRole(sheetId, user, role));
        } else {
            given.setRole(role);
            roles.flush();
        }
        audit.change("ROLE_SET", sheetId, by, "user=" + user, "role=" + role.name().toLowerCase());
        return given;
    }

    /** The sheet's permission matrix as set: for each action, the roles that may take it as a comma
     * separated list, blank for its standing rule. */
    @Transactional(readOnly = true)
    public Map<Action, String> permissions(String sheetId) {
        Map<Action, String> matrix = new EnumMap<>(Action.class);
        for (Action action : Action.values()) matrix.put(action, "");
        for (SheetPermission set : permissions.findBySheetId(sheetId)) matrix.put(set.getAction(), set.getRoles());
        return matrix;
    }

    /** Whether the user's role on the sheet may take {@code action}: one of the roles the matrix lists
     * for it, or of its standing rule when the matrix leaves it blank. */
    @Transactional(readOnly = true)
    public boolean allowed(String sheetId, String user, Action action) {
        String listed = permissions.findBySheetIdAndAction(sheetId, action).map(SheetPermission::getRoles).orElse("");
        Set<Role> may = listed.isBlank() ? action.standing() : rolesOf(listed);
        return may.contains(roleOf(sheetId, user));
    }

    /** Set the roles that may take {@code action} on the sheet: a comma separated list of roles, or blank
     * for its standing rule. */
    @Transactional
    public void setPermission(String sheetId, String by, Action action, String roles) {
        if (!sheets.existsById(sheetId)) throw new SheetNotFoundException();
        SheetPermission set = permissions.findBySheetIdAndAction(sheetId, action).orElse(null);
        if (set == null) {
            permissions.save(new SheetPermission(sheetId, action, roles));
        } else {
            set.setRoles(roles);
        }
        permissions.flush();
        audit.change("SETTING_CHANGED", sheetId, by, "key=perm-" + action.key(), "value=" + roles);
    }

    private static Set<Role> rolesOf(String listed) {
        Set<Role> roles = EnumSet.noneOf(Role.class);
        for (String role : listed.split(",")) {
            if (!role.isBlank()) roles.add(Role.valueOf(role.trim().toUpperCase(Locale.ROOT)));
        }
        return roles;
    }

    /** The clerk limit in force on the sheet's today; null when there is none. */
    @Transactional(readOnly = true)
    public BigDecimal clerkLimit(String sheetId) {
        return dated.clerkLimit(sheetId);
    }

    /** Record the sheet's clerk limit from {@code from} (the sheet's today when null); null records no limit. */
    @Transactional
    public void setClerkLimit(String sheetId, String by, BigDecimal limit, LocalDate from) {
        record(sheetId, by, DatedSettings.CLERK_LIMIT, limit == null ? null : limit.toPlainString(), from, false);
    }

    /** The floor in force on the sheet's today. */
    @Transactional(readOnly = true)
    public BigDecimal floor(String sheetId) {
        return dated.floorOn(sheetId, today(sheetId));
    }

    /** Record the sheet's floor from {@code from} (the sheet's today when null); the live dues of the
     * claims dated from then, and so the figures, follow it. */
    @Transactional
    public void setFloor(String sheetId, String by, BigDecimal floor, LocalDate from) {
        record(sheetId, by, DatedSettings.FLOOR, floor.toPlainString(), from, true);
    }

    /** The cap in force on the sheet's today, the most a person's due-total can be; null when there is none. */
    @Transactional(readOnly = true)
    public BigDecimal cap(String sheetId) {
        return dated.cap(sheetId);
    }

    /** Record the sheet's cap from {@code from} (the sheet's today when null); null records no cap. The
     * due-totals, and so the figures, follow the cap in force on the sheet's today. */
    @Transactional
    public void setCap(String sheetId, String by, BigDecimal cap, LocalDate from) {
        record(sheetId, by, DatedSettings.CAP, cap == null ? null : cap.toPlainString(), from, true);
    }

    /** The sheet's terms in force on its today, in days. */
    @Transactional(readOnly = true)
    public int terms(String sheetId) {
        return dated.termsOn(sheetId, today(sheetId));
