package net.officefloor.hq.app.rate;


/** The rates each grade has on each sheet, each from its from-date on (or from the beginning of time)
 * through its to-date (or with no end).
 * Setting a grade's rate for a from-date it already has a rate for replaces that rate. */
@Service
public class RateService {

    private final RateRepository rates;
    private final SheetRepository sheets;
    private final Audit audit;
    private final RollupService rollup;
    private final ClaimRepository claims;
    private final PersonRepository people;

    public RateService(RateRepository rates, SheetRepository sheets, Audit audit, RollupService rollup,
            ClaimRepository claims, PersonRepository people) {
        this.claims = claims;
        this.people = people;
        this.rates = rates;
        this.sheets = sheets;
        this.audit = audit;
        this.rollup = rollup;
    }

    /** The sheet's rates, by grade, then by from-date. */
    @Transactional(readOnly = true)
    public List<Rate> list(String sheetId) {
        return rates.findBySheetIdOrderByGradeAndFrom(sheetId);
    }

    @Transactional
    public Rate set(String sheetId, String user, String grade, LocalDate from, LocalDate to, BigDecimal pct) {
        if (!sheets.existsById(sheetId)) {
            throw new SheetNotFoundException();
        }
        if (from != null && to != null && to.isBefore(from)) {
            throw new RateRefusedException("A rate's to-date cannot be before its from-date.");
        }
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        Rate rate = (from == null ? rates.findUndated(sheetId, grade)
                : rates.findBySheetIdAndGradeAndFrom(sheetId, grade, from)).orElse(null);
        if (rate == null) {
            rate = rates.saveAndFlush(new Rate(sheetId, grade, from, to, pct));
        } else {
            rate.setPct(pct);
            rate.setTo(to);
            rates.flush();
        }
        List<String> fields = new ArrayList<>(List.of("grade=" + grade,
                "rate=" + rate.getPct().setScale(2, RoundingMode.UNNECESSARY).toPlainString()));
        if (from != null) fields.add("from=" + from);
        if (to != null) fields.add("to=" + to);
        audit.change("RATE_SET", sheetId, user, fields.toArray(String[]::new));
        rollup.recordSince(sheetId, user, before);
        return rate;
    }

    /** How many OPEN and PENDING claims would show a different due, and by how much in all (new minus
     * current), were {@code pct} the grade's rate on every date. */
    public record Preview(int count, BigDecimal diff) {
    }

    /** A preview of the grade's rate at {@code pct} on every date over the OPEN and PENDING claims of the
     * people on the grade on each claim's date; a claim a statement binds does not change. Saves nothing. */
    @Transactional(readOnly = true)
    public Preview preview(String sheetId, String grade, BigDecimal pct) {
        Map<Long, Person> byId = people.findBySheetIdOrderByIdAsc(sheetId).stream()
                .collect(Collectors.toMap(Person::getId, Function.identity()));
        RollupService.Basis live = rollup.live(sheetId);
        RollupService.Basis previewed = RollupService.withRate(live, grade, pct);
        int count = 0;
        BigDecimal diff = BigDecimal.ZERO.setScale(2);
        for (Claim claim : claims.findBySheetIdOrderByListedDescIdDesc(sheetId)) {
            Person person = byId.get(claim.getPersonId());
            if (person == null || !claim.getStatus().isOpen() || !grade.equals(person.gradeOn(claim.getDate()))) continue;
            BigDecimal now = rollup.shownOf(claim, person, live);
            BigDecimal then = rollup.shownOf(claim, person, previewed);
            if (Objects.equals(now, then) || (now != null && then != null && now.compareTo(then) == 0)) continue;
            count++;
            diff = diff.add(then == null ? BigDecimal.ZERO : then).subtract(now == null ? BigDecimal.ZERO : now);
        }
        return new Preview(count, diff.setScale(2, RoundingMode.HALF_EVEN));
    }
}
package net.officefloor.hq.app.holiday;


/** The holidays on a sheet. A claim's due-by is the terms-th business day after the date it counts from,
 * skipping every Saturday, Sunday and holiday on the sheet (see {@link #dueBy}); a holiday added later
 * re-fixes the due-by of every claim not SETTLED or VOID whose due-by is on or after it (see {@link #add}). */
@Service
public class HolidayService {

    private final SheetRepository sheets;
    private final SheetHolidayRepository holidays;
    private final ClaimRepository claims;
    private final RollupService rollup;
    private final Audit audit;

    public HolidayService(SheetRepository sheets, SheetHolidayRepository holidays, ClaimRepository claims,
            RollupService rollup, Audit audit) {
        this.sheets = sheets;
        this.holidays = holidays;
        this.claims = claims;
        this.rollup = rollup;
        this.audit = audit;
    }

    /** The sheet's holidays, earliest first. */
    @Transactional(readOnly = true)
    public List<SheetHoliday> holidays(String sheetId) {
        return holidays.findBySheetIdOrderByDateAsc(sheetId);
    }

    /** Add a holiday on {@code date}; refused when the date is already on the sheet's list. Every claim on
     * the sheet that is not SETTLED or VOID and whose due-by is on or after {@code date} has its due-by
     * worked out again from its date, with the terms it was fixed with, over the sheet's holidays now. */
    @Transactional
    public SheetHoliday add(String sheetId, String by, LocalDate date) {
        sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new);
        if (holidays.existsBySheetIdAndDate(sheetId, date)) throw new HolidayTakenException();
        RollupService.Snapshot before = rollup.snapshot(sheetId);
        SheetHoliday added = holidays.saveAndFlush(new SheetHoliday(sheetId, date));
        redate(sheetId, date);
        audit.change("HOLIDAY_ADDED", sheetId, by, "date=" + date);
        rollup.recordSince(sheetId, by, before);
        return added;
    }

    /** The due-by of a claim counting from {@code from} with {@code terms}: the terms-th business day
     * after it, counting forward from the day after and skipping every Saturday, Sunday and holiday on
     * the sheet; with terms of 0, {@code from} itself. */
    @Transactional(readOnly = true)
    public LocalDate dueBy(String sheetId, LocalDate from, int terms) {
        return dueBy(offOn(sheetId), from, terms);
    }

    private void redate(String sheetId, LocalDate holiday) {
        Set<LocalDate> off = offOn(sheetId);
        for (Claim claim : claims.findBySheetIdOrderByListedDescIdDesc(sheetId)) {
            if (claim.getStatus() == ClaimStatus.SETTLED || claim.getStatus() == ClaimStatus.VOID) continue;
            if (claim.getDueBy() == null || claim.getDueBy().isBefore(holiday)) continue;
            LocalDate dueBy = dueBy(off, claim.getDate(), claim.getTerms());
            if (!dueBy.equals(claim.getDueBy())) claim.setDueBy(dueBy);
        }
        claims.flush();
    }

    private Set<LocalDate> offOn(String sheetId) {
        return holidays.findBySheetIdOrderByDateAsc(sheetId).stream().map(SheetHoliday::getDate)
                .collect(Collectors.toSet());
    }

    private static LocalDate dueBy(Set<LocalDate> off, LocalDate from, int terms) {
        LocalDate on = from;
        for (int counted = 0; counted < terms;) {
            on = on.plusDays(1);
            if (isBusinessDay(off, on)) counted++;
        }
        return on;
    }

    private static boolean isBusinessDay(Set<LocalDate> off, LocalDate date) {
        DayOfWeek day = date.getDayOfWeek();
        return day != DayOfWeek.SATURDAY && day != DayOfWeek.SUNDAY && !off.contains(date);
    }
}

