package net.officefloor.hq.app.claim;


/** Status changes asked of several claims at once. Each claim changes in its own transaction, through
 * {@link ClaimService}, so a refused one changes (and records) nothing while the others go through,
 * except a bulk settle, which is all or nothing in one transaction. A
 * viewer's bulk change, or one on an archived sheet, goes through with nothing done: every claim asked
 * is refused. */
@Service
public class ClaimBulkService {

    /** How a bulk change went: the claims it changed, and how many it refused. */
    public record Outcome(List<Claim> changed, int refused) {
    }

    private final ClaimService service;
    private final ClaimRepository claims;
    private final PersonRepository people;
    private final SettingsService settings;
    private final SheetRepository sheets;
    private final TransactionTemplate transactions;

    public ClaimBulkService(ClaimService service, ClaimRepository claims, PersonRepository people,
            SettingsService settings, SheetRepository sheets, PlatformTransactionManager transactionManager) {
        this.transactions = new TransactionTemplate(transactionManager);
        this.sheets = sheets;
        this.service = service;
        this.claims = claims;
        this.people = people;
        this.settings = settings;
    }

    /** Open each of the claims that can be opened, in list order (people in the order they were
     * added, each person's claims newest first), so they are numbered in that order; any that cannot
     * be opened (or is not on the sheet) is left as it is and counted as refused. */
    public Outcome open(String sheetId, String user, Collection<Long> claimIds) {
        return change(sheetId, user, claimIds, ClaimStatus.OPEN);
    }

    /** Settle the claims all or nothing, by exactly the rules of settling one claim (one that goes to
     * PENDING instead counts as settled): when any of them cannot be settled (or is not on the sheet)
     * none is settled, every one counts as refused and nothing is written. Otherwise each is settled in
     * list order, and they are the sheet's next settle batch: each carries the batch's number, and
     * BATCH_SETTLED is recorded after the claims' own lines. */
    public Outcome settle(String sheetId, String user, Collection<Long> claimIds) {
        Set<Long> asked = Set.copyOf(claimIds);
        if (refusesAll(sheetId, user)) return new Outcome(List.of(), asked.size());
        Outcome outcome = transactions.execute(status -> {
            List<Claim> found = inListOrder(sheetId, asked);
            if (found.size() != asked.size()) return null;
            List<Claim> changed = new ArrayList<>();
            for (Claim claim : found) {
                try {
                    changed.add(service.changeStatus(sheetId, user, claim.getId(), ClaimStatus.SETTLED));
                } catch (ClaimStatusChangeException | ClaimPeriodClosedException | ClaimSelfSettleException | ClaimProofRequiredException | ClaimNoteRequiredException | ClaimNotFoundException | ClaimNotStewardException
                        | PersonNotFoundException e) {
                    status.setRollbackOnly();
                    return null;
                }
            }
            if (changed.isEmpty()) return new Outcome(changed, 0);
            return new Outcome(service.settleBatch(sheetId, user, changed), 0);
        });
        return outcome == null ? new Outcome(List.of(), asked.size()) : outcome;
    }

    /** Move each of the claims that can be moved to the person, in list order, by exactly the rules of
     * moving one claim (each move records its CLAIM_REASSIGNED and rollup lines); any that cannot be
     * moved (or is not on the sheet) is left as it is and counted as refused. */
    public Outcome reassign(String sheetId, String user, Collection<Long> claimIds, long personId) {
        Set<Long> asked = Set.copyOf(claimIds);
        if (refusesAll(sheetId, user)) return new Outcome(List.of(), asked.size());
        List<Claim> found = inListOrder(sheetId, asked);
        int refused = asked.size() - found.size();
        List<Claim> changed = new ArrayList<>();
        for (Claim claim : found) {
            try {
                changed.add(service.reassignOfBulk(sheetId, user, claim.getId(), personId));
            } catch (ClaimReassignException | ClaimPeriodClosedException | ClaimNotFoundException | ClaimNotStewardException
                    | PersonNotFoundException | PersonRetiredException e) {
                refused++;
            }
        }
        return new Outcome(changed, refused);
    }

    private boolean refusesAll(String sheetId, String user) {
        return settings.roleOf(sheetId, user) == Role.VIEWER
                || sheets.findById(sheetId).map(Sheet::isArchived).orElse(false);
    }

    /** The claims asked that are on the sheet: people in the order they were added, each person's
     * claims newest first. */
    private List<Claim> inListOrder(String sheetId, Set<Long> asked) {
        Map<Long, Integer> personOrder = new HashMap<>();
        List<Person> listed = people.findBySheetIdOrderByIdAsc(sheetId);
        for (int i = 0; i < listed.size(); i++) personOrder.put(listed.get(i).getId(), i);
        return claims.findBySheetIdOrderByListedDescIdDesc(sheetId).stream()
                .filter(c -> asked.contains(c.getId()))
                .sorted(Comparator.comparing((Claim c) -> personOrder.getOrDefault(c.getPersonId(), Integer.MAX_VALUE))
                        .thenComparing(Claim::getListed, Comparator.reverseOrder())
                        .thenComparing(Claim::getId, Comparator.reverseOrder()))
                .toList();
    }

    private Outcome change(String sheetId, String user, Collection<Long> claimIds, ClaimStatus next) {
        Set<Long> asked = Set.copyOf(claimIds);
        if (refusesAll(sheetId, user)) return new Outcome(List.of(), asked.size());
        List<Claim> found = inListOrder(sheetId, asked);
        int refused = asked.size() - found.size();
        List<Claim> changed = new ArrayList<>();
        for (Claim claim : found) {
            try {
                changed.add(service.changeStatus(sheetId, user, claim.getId(), next));
            } catch (ClaimStatusChangeException | ClaimPeriodClosedException | ClaimSelfSettleException | ClaimProofRequiredException | ClaimNoteRequiredException | ClaimNotFoundException | ClaimNotStewardException
                    | PersonNotFoundException e) {
                refused++;
            }
        }
        return new Outcome(changed, refused);
    }
}
package net.officefloor.hq.app.paste;


/** Adds a DRAFT claim per pasted line of {@code name,amount,date,note}, in order, for the person on the
 * sheet with that name (compared as names are). The date may be blank (the sheet's today); the note may
 * hold commas, or be left out. Each line is held to the claim form's rules; it is one change: when any
 * line is refused no claim is added, and nothing is recorded. Blank lines are skipped. A note ending in
 * {@code " #<reference>"} gives the claim that external reference, which is not part of the note. */
@Service
public class PasteService {

    /** An amount as the claim form takes it. */
    private static final Pattern AMOUNT = Pattern.compile("\\s*-?\\d{1,10}(\\.\\d{1,2})?\\s*");

    /** The longest note the claim form takes. */
    private static final int NOTE_MAX = 500;

    /** The longest reference the claim form takes. */
    private static final int REF_MAX = 120;

    private final PersonRepository people;
    private final ClaimService claimService;

    public PasteService(PersonRepository people, ClaimService claimService) {
        this.people = people;
        this.claimService = claimService;
    }

    /** The claims added, in the order of their lines. */
    @Transactional
    public List<Claim> paste(String sheetId, String user, String text) {
        List<Claim> added = new ArrayList<>();
        for (String line : text.split("\\r?\\n")) {
            if (line.isBlank()) continue;
            String[] fields = line.split(",", 4);
            if (fields.length < 2 || fields[0].isBlank() || !AMOUNT.matcher(fields[1]).matches()) {
                throw new PasteLineException();
            }
            Person person = people.findBySheetIdAndNameKey(sheetId, Person.keyOf(fields[0]))
                    .orElseThrow(PersonNotFoundException::new);
            String note = fields.length > 3 ? fields[3].trim() : "";
            String ref = null;
            int hash = note.lastIndexOf(" #");
            if (hash >= 0 && !note.substring(hash + 2).isBlank()) {
                ref = note.substring(hash + 2).trim();
                note = note.substring(0, hash).trim();
            }
            if (note.length() > NOTE_MAX || (ref != null && ref.length() > REF_MAX)) throw new PasteLineException();
            BigDecimal amount = new BigDecimal(fields[1].trim()).setScale(2);
            added.add(claimService.add(sheetId, user, person.getId(), amount, dateOf(fields), note, null, ref));
        }
        if (added.isEmpty()) throw new PasteLineException();
        return added;
    }

    /** The line's date; null when it is blank or left out. */
    private static LocalDate dateOf(String[] fields) {
        if (fields.length < 3 || fields[2].isBlank()) return null;
        try {
            return LocalDate.parse(fields[2].trim());
        } catch (DateTimeParseException e) {
            throw new PasteLineException();
        }
    }
}
package net.officefloor.hq.app.quickadd;


/** Adds a DRAFT claim, dated the sheet's today with an empty note, for a person named on the sheet,
 * first adding them with grade A when no one has that name. It is one change: when the claim is
 * refused the person is not added either, and nothing is recorded. */
@Service
public class QuickAddService {

    /** The grade a person added by a quick-add is given. */
    static final String GRADE = "A";

    public record Added(Person person, Claim claim) {
    }

    private final PersonRepository people;
    private final PersonService personService;
    private final ClaimService claimService;

    public QuickAddService(PersonRepository people, PersonService personService, ClaimService claimService) {
        this.people = people;
        this.personService = personService;
        this.claimService = claimService;
    }

    @Transactional
    public Added add(String sheetId, String user, String name, BigDecimal amount) {
        Person person = people.findBySheetIdAndNameKey(sheetId, Person.keyOf(name))
                .orElseGet(() -> personService.add(sheetId, user, name, GRADE, null));
        Claim claim = claimService.add(sheetId, user, person.getId(), amount, null, "", null);
        return new Added(person, claim);
    }
}
package net.officefloor.hq.app.person;


/** A grade given to several people at once. Each person is saved in their own transaction, through
 * {@link PersonService#update}, exactly as the person form saves them (keeping their name and terms),
 * so each records its own PERSON_EDITED and rollup lines. A viewer's bulk grade, or one on an archived
 * sheet, goes through with nothing done: no one is changed. */
@Service
public class PersonBulkService {

    private final PersonService service;
    private final PersonRepository people;
    private final SettingsService settings;
    private final SheetRepository sheets;

    public PersonBulkService(PersonService service, PersonRepository people, SettingsService settings,
            SheetRepository sheets) {
        this.service = service;
        this.people = people;
        this.settings = settings;
        this.sheets = sheets;
    }

    /** Gives each of the people {@code grade} from {@code from} (the sheet's today when left out), in
     * list order (the order they were added); those not on the sheet, or saved by someone else while
     * this runs, are left as they are. The people it changed. */
    public List<Person> grade(String sheetId, String user, Collection<Long> personIds, String grade, LocalDate from) {
        Set<Long> asked = Set.copyOf(personIds);
        if (settings.roleOf(sheetId, user) == Role.VIEWER) return List.of();
        if (sheets.findById(sheetId).map(Sheet::isArchived).orElse(false)) return List.of();
        List<Person> listed = people.findBySheetIdOrderByIdAsc(sheetId).stream()
                .filter(p -> asked.contains(p.getId()))
                .toList();
        List<Person> changed = new ArrayList<>();
        for (Person person : listed) {
            try {
                changed.add(service.update(sheetId, user, person.getId(), person.getVersion(), person.getName(),
                        grade, from, person.getTerms(), person.getContact()));
            } catch (PersonStaleException | PersonNotFoundException | ObjectOptimisticLockingFailureException e) {
                // Left as it is.
            }
        }
        return changed;
    }
}
package net.officefloor.hq.app.voidreason;


/** The void reasons on a sheet. While the list is not empty, a void of a claim on the sheet names one
 * of them (see {@link #refuseUnlisted}). */
@Service
public class VoidReasonService {

    private final SheetRepository sheets;
    private final SheetVoidReasonRepository reasons;
    private final Audit audit;

    public VoidReasonService(SheetRepository sheets, SheetVoidReasonRepository reasons, Audit audit) {
        this.sheets = sheets;
        this.reasons = reasons;
        this.audit = audit;
    }

    /** The sheet's void reasons, in the order they were added. */
    @Transactional(readOnly = true)
    public List<SheetVoidReason> reasons(String sheetId) {
        return reasons.findBySheetIdOrderByIdAsc(sheetId);
    }

    /** Add {@code reason} (trimmed, not blank); refused when it is already on the sheet's list. */
    @Transactional
    public SheetVoidReason add(String sheetId, String by, String reason) {
        sheets.findById(sheetId).orElseThrow(SheetNotFoundException::new);
        if (reasons.existsBySheetIdAndReason(sheetId, reason)) throw new VoidReasonTakenException();
        SheetVoidReason added = reasons.saveAndFlush(new SheetVoidReason(sheetId, reason));
        audit.change("VOID_REASON_ADDED", sheetId, by, "reason=" + reason);
        return added;
    }

    /** The reason a void on the sheet is given: null when the sheet's list is empty; refused when the
     * list is not empty and {@code reason} is blank or not on it. */
    @Transactional(readOnly = true)
    public String refuseUnlisted(String sheetId, String reason) {
        if (!reasons.existsBySheetId(sheetId)) return null;
        String given = reason == null ? "" : reason.trim();
        if (given.isEmpty() || !reasons.existsBySheetIdAndReason(sheetId, given)) throw new VoidReasonRequiredException();
        return given;
    }
}
package net.officefloor.hq.app.history;


/** Refuses every change asked from a screen showing its sheet as of a date (one whose requests carry the
 * {@value #HEADER} header) before it reaches its controller, so it writes nothing. Reads go through, as does
 * loading the sheet; a bulk change goes through to its controller, which refuses each claim asked. */
@Configuration
public class AsOfGuard implements WebMvcConfigurer, HandlerInterceptor {

    /** The header a screen showing its sheet as of a date sends that date in (YYYY-MM-DD). */
    public static final String HEADER = "X-As-Of";

    @Override
    public void addInterceptors(InterceptorRegistry registry) {
        registry.addInterceptor(this)
                .addPathPatterns("/api/sheets/*/**")
                .excludePathPatterns("/api/sheets/*/load", "/api/sheets/*/claims/bulk-*");
    }

    @Override
    public boolean preHandle(HttpServletRequest request, HttpServletResponse response, Object handler) {
        if (HttpMethod.GET.matches(request.getMethod()) || HttpMethod.HEAD.matches(request.getMethod())) return true;
        String asOf = request.getHeader(HEADER);
        if (asOf != null && !asOf.isBlank()) throw new AsOfRefusedException();
        return true;
    }
}
